use fusion_lab::*;
fn old_bits(s:&ReplaySnapshot)->Vec<u64>{s.estimate().position.into_iter().chain(s.estimate().velocity).chain(s.covariance().iter().flatten().copied()).chain(s.held_position()).chain(s.integrated_position()).map(f64::to_bits).collect()}
fn new_bits(s:&HistorySnapshot)->Vec<u64>{s.estimate().position.into_iter().chain(s.estimate().velocity).chain(s.covariance().into_iter().flatten()).chain(s.held_position()).chain(s.integrated_position()).map(f64::to_bits).collect()}
fn main(){
 let mut comparisons=0usize;let mut cases=0usize;
 for seed in 0..3u32 {for (p,v,q) in [(5.0,2.0,0.0),(1.0,0.15,0.1),(10.0,3.0,1.0)] {let model=ReplayModel::new(p,v,q).unwrap();
  let mut input=Vec::new();for (sensor,period,sid) in [(Sensor::Position,20u32,0u32),(Sensor::Velocity,5u32,1u32)] {for sample in (0..=200).step_by(period as usize){let seq=sample/period;let delay=(seq*13+seed*7+sid*3)%26;let value=[f64::from((seq*7+sid*3)%31)-15.0,f64::from((seq*11+seed*2)%29)-14.0];input.push(Observation::new(sensor,seq,sample,sample+delay,value).unwrap());}}
  let trace=Trace::new(2,128,[None,None],input.clone()).unwrap();let legacy=replay_delivery(&model,&trace).unwrap();assert!(legacy.ledger().iter().all(|e|!matches!(e.outcome(),DeliveryOutcome::QueueFullDrop|DeliveryOutcome::ScriptedLoss)));
  for w in [0u32,1,7,20,25,500] {let result=replay_history(&model,&trace,&HistoryPlan::new(w).unwrap()).unwrap();assert_eq!(result.snapshots().len(),201);
   for tick in 0..=200u32 {let known=input.iter().filter(|o|o.planned_arrival_tick()<=tick && o.planned_arrival_tick()-o.sample_tick()<=w).map(|o|Observation::new(o.id().sensor(),o.id().sequence(),o.sample_tick(),o.sample_tick(),o.value()).unwrap()).collect();let reference=Trace::new(2,128,[None,None],known).unwrap();let expected=replay_delivery(&model,&reference).unwrap();assert_eq!(new_bits(&result.snapshots()[tick as usize]),old_bits(&expected.snapshots()[tick as usize]),"seed={seed} model={p},{v},{q} w={w} tick={tick}");comparisons+=1;}
   assert_eq!(result.ledger().len(),input.len());for e in result.ledger(){let expected=if e.planned_arrival_tick()>200 {HistoryOutcome::UndeliveredAtHorizon}else if e.planned_arrival_tick()==e.sample_tick(){HistoryOutcome::AcceptedOnTime}else if e.planned_arrival_tick()-e.sample_tick()<=w{HistoryOutcome::CorrectedLate}else{HistoryOutcome::TooOldDrop};assert_eq!(e.outcome(),expected);assert_eq!(e.decision_tick(),e.planned_arrival_tick().min(200));}cases+=1;
  }
 }}
 let m=ReplayModel::new(5.0,2.0,0.0).unwrap();let t=Trace::new(1,128,[None,None],vec![Observation::new(Sensor::Position,0,0,0,[1e308,1e308]).unwrap(),Observation::new(Sensor::Velocity,0,0,0,[1e308,1e308]).unwrap()]).unwrap();let old=replay_delivery(&m,&t).unwrap();let new=replay_history(&m,&t,&HistoryPlan::new(0).unwrap()).unwrap();assert_eq!(new.snapshots().len(),101);let mut first_nonfinite=None;for (a,b) in new.snapshots().iter().zip(old.snapshots()){assert_eq!(new_bits(a),old_bits(b));assert!(a.estimate().position.into_iter().chain(a.estimate().velocity).chain(a.covariance().into_iter().flatten()).all(f64::is_finite));if first_nonfinite.is_none()&&!a.integrated_position().into_iter().all(f64::is_finite){first_nonfinite=Some(a.tick());}}assert_eq!(first_nonfinite,Some(80));
 println!("DIFFERENTIAL_OK cases={cases} online_bit_comparisons={comparisons} windows=0,1,7,20,25,500 models=3 seeds=3 snapshots_each=201");println!("LEGACY_EXTREME_OK W0_all101snapshotbits_equal first_nonfinite_integration_tick={:?} filter_all_finite=true",first_nonfinite);
}
